// Autogenerated embedded HTML viewer for Raymond Knowledge Graph
const rawHtml = "<!DOCTYPE html>\n<html lang=\"en\" class=\"dark\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Raymond \u2014 Knowledge Graph Visualizer & Explorer</title>\n  <link rel=\"icon\" href=\"data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 100%22><text y=%22.9em%22 font-size=%2290%22>\ud83d\udd78\ufe0f</text></svg>\">\n  \n  <!-- Google Fonts: Plus Jakarta Sans & JetBrains Mono -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;700&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n\n  <!-- Tailwind CSS CDN -->\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n  <script>\n    tailwind.config = {\n      darkMode: 'class',\n      theme: {\n        extend: {\n          fontFamily: {\n            sans: ['\"Plus Jakarta Sans\"', '-apple-system', 'BlinkMacSystemFont', 'sans-serif'],\n            mono: ['\"JetBrains Mono\"', 'ui-monospace', 'monospace']\n          },\n          colors: {\n            brand: {\n              50: '#ecfdf5',\n              400: '#34d399',\n              500: '#10b981',\n              600: '#059669',\n              700: '#047857',\n            },\n            dark: {\n              950: '#090d16',\n              900: '#0f172a',\n              850: '#131d35',\n              800: '#1e293b',\n              700: '#334155',\n            }\n          }\n        }\n      }\n    }\n  </script>\n\n  <!-- Vis Network CDN -->\n  <script src=\"https://unpkg.com/vis-network@9.1.9/standalone/umd/vis-network.min.js\"></script>\n\n  <!-- Lucide Icons CDN -->\n  <script src=\"https://unpkg.com/lucide@latest\"></script>\n\n  <!-- Marked.js Markdown Parser -->\n  <script src=\"https://cdn.jsdelivr.net/npm/marked/marked.min.js\"></script>\n\n  <style>\n    body {\n      font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;\n      background: radial-gradient(circle at 50% 10%, #172554 0%, #090d16 60%, #030712 100%) !important;\n    }\n\n    code, pre, .font-mono {\n      font-family: 'JetBrains Mono', monospace !important;\n    }\n\n    /* Custom scrollbars */\n    ::-webkit-scrollbar {\n      width: 6px;\n      height: 6px;\n    }\n    ::-webkit-scrollbar-track {\n      background: rgba(15, 23, 42, 0.6);\n    }\n    ::-webkit-scrollbar-thumb {\n      background: rgba(255, 255, 255, 0.15);\n      border-radius: 3px;\n    }\n    ::-webkit-scrollbar-thumb:hover {\n      background: rgba(255, 255, 255, 0.3);\n    }\n\n    /* Markdown prose styles in inspector */\n    .prose-dark {\n      color: #cbd5e1;\n      font-size: 0.775rem;\n      line-height: 1.45rem;\n      word-break: break-word;\n    }\n    .prose-dark p {\n      margin-bottom: 0.6rem;\n    }\n    .prose-dark p:last-child {\n      margin-bottom: 0;\n    }\n    .prose-dark h1, .prose-dark h2, .prose-dark h3, .prose-dark h4 {\n      color: #f8fafc;\n      font-weight: 700;\n      margin-top: 0.9rem;\n      margin-bottom: 0.35rem;\n    }\n    .prose-dark h1 { font-size: 0.95rem; }\n    .prose-dark h2 { font-size: 0.875rem; border-bottom: 1px solid rgba(255, 255, 255, 0.1); padding-bottom: 0.2rem; }\n    .prose-dark h3 { font-size: 0.8rem; color: #38bdf8; }\n    .prose-dark ul, .prose-dark ol {\n      margin-left: 1.25rem;\n      margin-bottom: 0.6rem;\n    }\n    .prose-dark ul { list-style-type: disc; }\n    .prose-dark ol { list-style-type: decimal; }\n    .prose-dark li {\n      margin-bottom: 0.25rem;\n    }\n    .prose-dark code {\n      background-color: rgba(0, 0, 0, 0.4);\n      border: 1px solid rgba(255, 255, 255, 0.1);\n      color: #38bdf8;\n      padding: 0.15rem 0.35rem;\n      border-radius: 0.25rem;\n      font-size: 0.725rem;\n    }\n    .prose-dark pre {\n      background-color: rgba(0, 0, 0, 0.5);\n      border: 1px solid rgba(255, 255, 255, 0.1);\n      border-radius: 0.5rem;\n      padding: 0.6rem;\n      margin: 0.5rem 0;\n      overflow-x: auto;\n    }\n    .prose-dark pre code {\n      background: transparent;\n      border: 0;\n      padding: 0;\n      color: #a5f3fc;\n    }\n    .prose-dark blockquote {\n      border-left: 3px solid #10b981;\n      padding-left: 0.6rem;\n      color: #94a3b8;\n      font-style: italic;\n      margin: 0.5rem 0;\n    }\n    .prose-dark a {\n      color: #34d399;\n      text-decoration: underline;\n      text-underline-offset: 2px;\n    }\n    .prose-dark hr {\n      border: 0;\n      border-top: 1px solid rgba(255, 255, 255, 0.1);\n      margin: 0.75rem 0;\n    }\n    /* Vis network navigation overrides for sleek dark look */\n    .vis-network div.vis-navigation div.vis-button {\n      background-color: rgba(30, 41, 59, 0.8) !important;\n      border: 1px solid rgba(255, 255, 255, 0.15) !important;\n      border-radius: 8px !important;\n      box-shadow: 0 4px 10px rgba(0, 0, 0, 0.4) !important;\n      backdrop-filter: blur(8px);\n    }\n    .vis-network div.vis-navigation div.vis-button:hover {\n      background-color: rgba(51, 65, 85, 0.9) !important;\n      border-color: rgba(255, 255, 255, 0.3) !important;\n    }\n  </style>\n</head>\n<body class=\"text-slate-100 h-screen w-screen flex flex-col overflow-hidden antialiased select-none relative\">\n\n  <!-- ================= TOP NAVIGATION / HEADER ================= -->\n  <header class=\"h-14 border-b border-white/10 bg-dark-900/80 backdrop-blur-md px-4 flex items-center justify-between z-20 shrink-0 shadow-lg\">\n    <!-- Left: Brand & Status -->\n    <div class=\"flex items-center gap-3\">\n      <div class=\"flex items-center gap-2\">\n        <div class=\"w-8 h-8 rounded-lg flex items-center justify-center font-bold text-base shadow-lg\"\n             style=\"background: linear-gradient(135deg, #a855f7, #ec4899); box-shadow: 0 0 15px rgba(168, 85, 247, 0.4); border: 1px solid rgba(255, 255, 255, 0.2);\">\n          \ud83d\udd78\ufe0f\n        </div>\n        <div>\n          <div class=\"flex items-center gap-2\">\n            <span class=\"font-extrabold tracking-tight text-white text-base\">Raymond</span>\n            <span class=\"text-[11px] px-2 py-0.5 rounded-full bg-purple-950/80 text-purple-300 border border-purple-800/60 font-semibold tracking-wide\">Knowledge Graph</span>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"h-5 w-px bg-white/10 mx-1\"></div>\n\n      <!-- Live Connection Status Badge -->\n      <button id=\"btnConnectionStatus\" onclick=\"openSettingsModal()\" class=\"flex items-center gap-2 px-2.5 py-1 rounded-lg bg-white/5 hover:bg-white/10 border border-white/10 transition text-xs text-slate-300\">\n        <span id=\"statusIndicator\" class=\"w-2 h-2 rounded-full bg-slate-500\"></span>\n        <span id=\"statusText\">Not Connected</span>\n      </button>\n\n      <!-- Refresh Button -->\n      <button id=\"btnSync\" onclick=\"refreshData()\" title=\"Reload from source\" class=\"p-1.5 rounded-lg hover:bg-white/10 text-slate-400 hover:text-white transition border border-transparent hover:border-white/10\">\n        <i data-lucide=\"refresh-cw\" class=\"w-4 h-4\"></i>\n      </button>\n    </div>\n\n    <!-- Center: Search Bar & Auto-Focus -->\n    <div class=\"relative w-80 max-w-sm\">\n      <div class=\"relative\">\n        <i data-lucide=\"search\" class=\"w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none\"></i>\n        <input \n          type=\"text\" \n          id=\"searchInput\" \n          placeholder=\"Search entities, types, aliases...\" \n          class=\"w-full pl-9 pr-8 py-1.5 bg-white/5 border border-white/10 rounded-xl text-xs text-white placeholder-slate-400 focus:outline-none focus:border-purple-500 focus:ring-1 focus:ring-purple-500 transition shadow-inner\"\n          oninput=\"handleSearch(this.value)\"\n        >\n        <button id=\"btnClearSearch\" onclick=\"clearSearch()\" class=\"hidden absolute right-2.5 top-1/2 -translate-y-1/2 text-slate-400 hover:text-white text-xs\">\n          \u2715\n        </button>\n      </div>\n      <!-- Autocomplete Dropdown -->\n      <div id=\"searchDropdown\" class=\"hidden absolute top-full mt-1.5 left-0 right-0 max-h-60 overflow-y-auto bg-dark-900/95 backdrop-blur-xl border border-white/10 rounded-xl shadow-2xl z-50 py-1\"></div>\n    </div>\n\n    <!-- Right: Stats & Action Tools -->\n    <div class=\"flex items-center gap-2\">\n      <!-- Counters Pill -->\n      <div class=\"hidden md:flex items-center gap-3 px-3 py-1 bg-white/5 border border-white/10 rounded-xl text-xs text-slate-400 font-mono\">\n        <div><span id=\"statEntities\" class=\"text-purple-400 font-bold\">0</span> entities</div>\n        <div class=\"w-1 h-1 rounded-full bg-slate-600\"></div>\n        <div><span id=\"statRelations\" class=\"text-sky-400 font-bold\">0</span> relations</div>\n        <div class=\"w-1 h-1 rounded-full bg-slate-600\"></div>\n        <div><span id=\"statMemories\" class=\"text-pink-400 font-bold\">0</span> memories</div>\n      </div>\n\n      <!-- Quick Action Buttons -->\n      <div class=\"flex items-center gap-1 border-l border-white/10 pl-2\">\n        <button onclick=\"fitGraph()\" title=\"Fit View to All Nodes\" class=\"p-1.5 rounded-lg hover:bg-white/10 text-slate-400 hover:text-white transition border border-transparent hover:border-white/10\">\n          <i data-lucide=\"maximize\" class=\"w-4 h-4\"></i>\n        </button>\n        <button id=\"btnPhysicsToggle\" onclick=\"togglePhysics()\" title=\"Toggle Physics Simulation\" class=\"p-1.5 rounded-lg hover:bg-white/10 text-emerald-400 hover:text-emerald-300 transition border border-transparent hover:border-white/10\">\n          <i data-lucide=\"activity\" class=\"w-4 h-4\"></i>\n        </button>\n        <button id=\"btnLayoutToggle\" onclick=\"toggleLayoutMode()\" title=\"Toggle Hierarchical / Force Layout\" class=\"p-1.5 rounded-lg hover:bg-white/10 text-slate-400 hover:text-white transition border border-transparent hover:border-white/10\">\n          <i data-lucide=\"git-fork\" class=\"w-4 h-4\"></i>\n        </button>\n        <button onclick=\"exportPNG()\" title=\"Export PNG Screenshot\" class=\"p-1.5 rounded-lg hover:bg-white/10 text-slate-400 hover:text-white transition border border-transparent hover:border-white/10\">\n          <i data-lucide=\"camera\" class=\"w-4 h-4\"></i>\n        </button>\n        <button onclick=\"triggerJsonImport()\" title=\"Import Graph JSON (Offline / Zero-Runtime)\" class=\"p-1.5 rounded-lg hover:bg-white/10 text-slate-400 hover:text-white transition border border-transparent hover:border-white/10\">\n          <i data-lucide=\"upload\" class=\"w-4 h-4\"></i>\n        </button>\n        <input type=\"file\" id=\"jsonFileInput\" accept=\".json,application/json\" class=\"hidden\" onchange=\"handleFileImport(event)\">\n        <button onclick=\"openSettingsModal()\" title=\"Supabase API Settings\" class=\"p-1.5 rounded-lg hover:bg-white/10 text-slate-400 hover:text-white transition border border-transparent hover:border-white/10\">\n          <i data-lucide=\"settings\" class=\"w-4 h-4\"></i>\n        </button>\n      </div>\n    </div>\n  </header>\n\n  <!-- ================= MAIN WORKSPACE AREA ================= -->\n  <!-- Floating Filter Controls Bar (Left Top) -->\n  <div class=\"absolute top-16 left-3 z-10 flex flex-col gap-2 max-w-sm pointer-events-none\">\n    <!-- Entity Type Filter Chips -->\n    <div class=\"pointer-events-auto bg-dark-900/85 backdrop-blur-md border border-white/10 rounded-2xl p-2.5 shadow-2xl\">\n      <div class=\"flex items-center justify-between mb-2\">\n        <span class=\"text-[11px] font-bold text-slate-400 uppercase tracking-wider flex items-center gap-1.5\">\n          <i data-lucide=\"filter\" class=\"w-3 h-3 text-purple-400\"></i> Entity Types\n        </span>\n        <button onclick=\"resetFilters()\" class=\"text-[10px] text-purple-400 hover:underline font-semibold\">Reset</button>\n      </div>\n      <div id=\"typeFilterPills\" class=\"flex flex-wrap gap-1.5 max-h-32 overflow-y-auto pr-1\"></div>\n    </div>\n\n    <!-- Display Options -->\n    <div class=\"pointer-events-auto bg-dark-900/85 backdrop-blur-md border border-white/10 rounded-2xl p-2.5 shadow-2xl flex items-center justify-between text-xs\">\n      <label class=\"flex items-center gap-2 cursor-pointer select-none\">\n        <input type=\"checkbox\" id=\"chkShowSuperseded\" onchange=\"toggleSuperseded(this.checked)\" class=\"rounded bg-dark-800 border-slate-700 text-purple-500 focus:ring-0\">\n        <span class=\"text-slate-300 font-medium\">Show Superseded Links</span>\n      </label>\n      <span id=\"supersededCountPill\" class=\"text-[10px] font-mono px-1.5 py-0.5 rounded bg-red-950/60 text-red-400 border border-red-900/60\">0</span>\n    </div>\n\n    <!-- Hop Focus Mode Pill -->\n    <div id=\"focusModeBox\" class=\"hidden pointer-events-auto bg-dark-900/85 backdrop-blur-md border border-white/10 rounded-2xl p-2.5 shadow-2xl flex items-center justify-between text-xs\">\n      <div class=\"flex items-center gap-1.5 text-slate-300\">\n        <i data-lucide=\"crosshair\" class=\"w-3.5 h-3.5 text-emerald-400\"></i>\n        <span>Neighborhood Focus:</span>\n        <span id=\"focusEntityName\" class=\"font-bold text-white truncate max-w-[100px]\">Node</span>\n      </div>\n      <button onclick=\"clearFocusMode()\" class=\"text-xs text-red-400 hover:text-red-300 font-medium ml-2\">Exit</button>\n    </div>\n  </div>\n\n  <!-- Graph Canvas Container -->\n  <div id=\"graphContainer\" class=\"flex-1 w-full h-full\"></div>\n\n  <!-- Empty State Overlay when unauthenticated / no data loaded -->\n  <div id=\"emptyStateOverlay\" class=\"hidden absolute inset-0 top-14 z-20 flex flex-col items-center justify-center pointer-events-auto bg-dark-950/60 backdrop-blur-[2px]\">\n    <div class=\"max-w-md p-8 rounded-2xl bg-dark-900/90 border border-white/10 shadow-2xl text-center flex flex-col items-center gap-4\">\n      <div class=\"w-14 h-14 rounded-2xl bg-purple-500/10 border border-purple-500/30 flex items-center justify-center text-2xl shadow-inner\">\n        \ud83d\udd78\ufe0f\n      </div>\n      <div>\n        <h2 class=\"text-base font-bold text-white tracking-tight\">Raymond Knowledge Graph</h2>\n        <p class=\"text-xs text-slate-400 mt-1 leading-relaxed\">\n          No graph data loaded. Connect directly to your Raymond Supabase database, drop an exported JSON file, or load sample demo data.\n        </p>\n      </div>\n      <div class=\"flex flex-col sm:flex-row items-center gap-2.5 w-full pt-1\">\n        <button onclick=\"openSettingsModal()\" class=\"w-full sm:flex-1 py-2 px-3.5 rounded-xl bg-purple-600 hover:bg-purple-500 text-white font-medium text-xs flex items-center justify-center gap-2 transition shadow-lg shadow-purple-950/50\">\n          <i data-lucide=\"database\" class=\"w-3.5 h-3.5\"></i> Connect Supabase\n        </button>\n        <button onclick=\"triggerJsonImport()\" class=\"w-full sm:flex-1 py-2 px-3.5 rounded-xl bg-white/5 hover:bg-white/10 text-slate-200 border border-white/10 font-medium text-xs flex items-center justify-center gap-2 transition\">\n          <i data-lucide=\"upload\" class=\"w-3.5 h-3.5\"></i> Import JSON\n        </button>\n      </div>\n      <button onclick=\"loadDemoDataset()\" class=\"text-[11px] text-slate-500 hover:text-amber-300 transition flex items-center gap-1.5 mt-1\">\n        <i data-lucide=\"sparkles\" class=\"w-3 h-3 text-amber-400\"></i> Or explore with sample demo graph\n      </button>\n    </div>\n  </div>\n\n  <!-- Floating Drag-to-Connect Indicator Pill -->\n  <div id=\"dropConnectPill\" class=\"hidden fixed z-50 pointer-events-none bg-emerald-600/95 text-white font-semibold text-xs px-3.5 py-1.5 rounded-full shadow-2xl backdrop-blur-md border border-emerald-400 flex items-center gap-1.5 transition-opacity\">\n    <i data-lucide=\"link-2\" class=\"w-3.5 h-3.5 text-emerald-200\"></i>\n    <span id=\"dropConnectPillText\">Drop to connect</span>\n  </div>\n\n  <!-- Floating Action Toast Container -->\n  <div id=\"toastContainer\" class=\"fixed bottom-6 left-1/2 -translate-y-0 -translate-x-1/2 z-50 flex flex-col items-center gap-2 pointer-events-none\"></div>\n\n  <!-- ================= RIGHT SLIDE-OVER INSPECTOR DRAWER ================= -->\n  <aside id=\"inspectorDrawer\" class=\"fixed top-14 right-0 bottom-0 w-96 max-w-full border-l border-white/10 bg-dark-900/90 backdrop-blur-xl flex flex-col z-20 transition-transform duration-300 ease-in-out translate-x-full shadow-2xl\">\n    <!-- Drawer Header -->\n    <div class=\"h-14 border-b border-white/10 px-4 flex items-center justify-between shrink-0\">\n      <div class=\"flex items-center gap-2 overflow-hidden\">\n        <i id=\"inspectorIcon\" data-lucide=\"circle-dot\" class=\"w-4 h-4 text-purple-400 shrink-0\"></i>\n        <h2 id=\"inspectorTitle\" class=\"text-sm font-bold text-white truncate\">Inspector</h2>\n      </div>\n      <div class=\"flex items-center gap-1\">\n        <button id=\"btnToggleDrawerWidth\" onclick=\"toggleDrawerWidth()\" title=\"Toggle Wide View\" class=\"p-1 rounded-lg text-slate-400 hover:text-white hover:bg-white/10 transition\">\n          <i id=\"iconDrawerWidth\" data-lucide=\"maximize-2\" class=\"w-4 h-4\"></i>\n        </button>\n        <button onclick=\"closeInspector()\" class=\"p-1 rounded-lg text-slate-400 hover:text-white hover:bg-white/10 transition\">\n          <i data-lucide=\"x\" class=\"w-4 h-4\"></i>\n        </button>\n      </div>\n    </div>\n\n    <!-- Drawer Scrollable Content -->\n    <div id=\"inspectorContent\" class=\"flex-1 overflow-y-auto p-4 space-y-5 text-xs text-slate-300\">\n      <!-- Content will be rendered dynamically -->\n    </div>\n  </aside>\n\n  <!-- ================= SETTINGS & SUPABASE CREDENTIALS MODAL ================= -->\n  <div id=\"settingsModal\" class=\"hidden fixed inset-0 z-50 bg-black/75 backdrop-blur-md flex items-center justify-center p-4\">\n    <div class=\"w-full max-w-md bg-dark-900/95 border border-white/15 rounded-2xl shadow-2xl overflow-hidden flex flex-col backdrop-blur-2xl\">\n      <!-- Modal Header -->\n      <div class=\"px-5 py-4 border-b border-white/10 flex items-center justify-between\">\n        <div class=\"flex items-center gap-2\">\n          <div class=\"w-7 h-7 rounded-lg bg-purple-500/10 border border-purple-500/30 flex items-center justify-center text-purple-400\">\n            <i data-lucide=\"database\" class=\"w-4 h-4\"></i>\n          </div>\n          <h3 class=\"font-bold text-white text-sm\">Supabase Connection Settings</h3>\n        </div>\n        <button onclick=\"closeSettingsModal()\" class=\"text-slate-400 hover:text-white\">\n          <i data-lucide=\"x\" class=\"w-4 h-4\"></i>\n        </button>\n      </div>\n\n      <!-- Modal Body -->\n      <div class=\"p-5 space-y-4 text-xs\">\n        <p class=\"text-slate-400 leading-relaxed\">\n          Connect directly to your Supabase PostgreSQL tables (<code class=\"text-purple-400 font-mono\">public.entities</code>, <code class=\"text-purple-400 font-mono\">public.relations</code>, <code class=\"text-purple-400 font-mono\">public.memories</code>).\n        </p>\n\n        <div>\n          <label class=\"block text-slate-300 font-medium mb-1\">Supabase URL</label>\n          <input \n            type=\"url\" \n            id=\"cfgSupabaseUrl\" \n            placeholder=\"https://xyzcompany.supabase.co\" \n            class=\"w-full px-3 py-2 bg-dark-800/80 border border-white/10 rounded-xl text-white font-mono placeholder-slate-500 focus:outline-none focus:border-purple-500 focus:ring-1 focus:ring-purple-500\"\n          >\n        </div>\n\n        <div>\n          <label class=\"block text-slate-300 font-medium mb-1\">Supabase API Key (Anon or Service Role)</label>\n          <input \n            type=\"password\" \n            id=\"cfgSupabaseKey\" \n            placeholder=\"eyJh...\" \n            class=\"w-full px-3 py-2 bg-dark-800/80 border border-white/10 rounded-xl text-white font-mono placeholder-slate-500 focus:outline-none focus:border-purple-500 focus:ring-1 focus:ring-purple-500\"\n          >\n          <span class=\"text-[10px] text-slate-500 mt-1 block\">Saved in browser's local storage only. Never sent to any 3rd party.</span>\n        </div>\n\n        <div id=\"modalStatusAlert\" class=\"hidden p-3 rounded-lg border text-xs\"></div>\n      </div>\n\n      <!-- Modal Footer -->\n      <div class=\"px-5 py-3 border-t border-white/10 bg-dark-950 flex items-center justify-between\">\n        <button onclick=\"loadDemoDataset()\" class=\"px-3 py-1.5 rounded-xl bg-white/5 hover:bg-white/10 text-slate-300 border border-white/10 transition text-xs flex items-center gap-1.5\">\n          <i data-lucide=\"sparkles\" class=\"w-3.5 h-3.5 text-amber-400\"></i> Load Demo Graph\n        </button>\n        <div class=\"flex items-center gap-2\">\n          <button onclick=\"closeSettingsModal()\" class=\"px-3 py-1.5 rounded-xl hover:bg-white/10 text-slate-400 hover:text-white transition text-xs\">\n            Cancel\n          </button>\n          <button onclick=\"saveAndConnectSupabase()\" class=\"px-4 py-1.5 rounded-xl bg-purple-600 hover:bg-purple-500 text-white font-semibold shadow-lg shadow-purple-900/40 transition text-xs flex items-center gap-1.5\">\n            <i data-lucide=\"check\" class=\"w-3.5 h-3.5\"></i> Connect & Sync\n          </button>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- ================= JAVASCRIPT APPLICATION LOGIC ================= -->\n  <script>\n    // --- STATE MANAGEMENT ---\n    let network = null;\n    let rawEntities = [];\n    let rawRelations = [];\n    let rawMemories = [];\n    let rawMemoryEntities = [];\n    \n    let isPhysicsActive = true;\n    let isHierarchical = false;\n    let activeTypeFilters = new Set();\n    let showSuperseded = false;\n    let selectedEntityId = null;\n    let focusCenterEntityId = null;\n    let focusHopDepth = 0; // 0 = all nodes\n\n    // Visual Palette by Entity Type\n    const TYPE_STYLES = {\n      concept: { bg: '#8B5CF6', border: '#A78BFA', highlight: '#C4B5FD', badge: 'bg-purple-950/80 text-purple-300 border-purple-800/80' },\n      component: { bg: '#0284C7', border: '#38BDF8', highlight: '#7DD3FC', badge: 'bg-sky-950/80 text-sky-300 border-sky-800/80' },\n      technology: { bg: '#059669', border: '#34D399', highlight: '#6EE7B7', badge: 'bg-emerald-950/80 text-emerald-300 border-emerald-800/80' },\n      decision: { bg: '#D97706', border: '#FBBF24', highlight: '#FDE68A', badge: 'bg-amber-950/80 text-amber-300 border-amber-800/80' },\n      agent: { bg: '#E11D48', border: '#FB7185', highlight: '#FDA4AF', badge: 'bg-rose-950/80 text-rose-300 border-rose-800/80' },\n      system: { bg: '#4F46E5', border: '#818CF8', highlight: '#A5B4FC', badge: 'bg-indigo-950/80 text-indigo-300 border-indigo-800/80' },\n      tool: { bg: '#0D9488', border: '#2DD4BF', highlight: '#5EEAD4', badge: 'bg-teal-950/80 text-teal-300 border-teal-800/80' },\n      algorithm: { bg: '#EC4899', border: '#F472B6', highlight: '#FBCFE8', badge: 'bg-pink-950/80 text-pink-300 border-pink-800/80' },\n      protocol: { bg: '#06B6D4', border: '#67E8F9', highlight: '#CFFAFE', badge: 'bg-cyan-950/80 text-cyan-300 border-cyan-800/80' },\n      wayland_interface: { bg: '#0891B2', border: '#22D3EE', highlight: '#A5F3FC', badge: 'bg-cyan-950/80 text-cyan-300 border-cyan-800/80' },\n      library: { bg: '#3B82F6', border: '#60A5FA', highlight: '#BFDBFE', badge: 'bg-blue-950/80 text-blue-300 border-blue-800/80' },\n      project: { bg: '#6366F1', border: '#818CF8', highlight: '#C7D2FE', badge: 'bg-indigo-950/80 text-indigo-300 border-indigo-800/80' },\n      reference_project: { bg: '#64748B', border: '#94A3B8', highlight: '#CBD5E1', badge: 'bg-slate-800 text-slate-300 border-slate-700' },\n      memory: { bg: '#64748B', border: '#94A3B8', highlight: '#CBD5E1', badge: 'bg-slate-800 text-slate-300 border-slate-600' },\n      unlinked_memory: { bg: '#64748B', border: '#94A3B8', highlight: '#CBD5E1', badge: 'bg-slate-800 text-slate-300 border-slate-600' },\n      default: { bg: '#475569', border: '#94A3B8', highlight: '#CBD5E1', badge: 'bg-slate-800 text-slate-300 border-slate-700' }\n    };\n\n    function getTypeStyle(type) {\n      const key = (type || 'concept').toLowerCase();\n      if (TYPE_STYLES[key]) return TYPE_STYLES[key];\n      // Deterministic vibrant HSL palette fallback for any dynamic/unknown entity type\n      let hash = 0;\n      for (let i = 0; i < key.length; i++) hash = key.charCodeAt(i) + ((hash << 5) - hash);\n      const h = Math.abs(hash) % 360;\n      return {\n        bg: `hsl(${h}, 65%, 48%)`,\n        border: `hsl(${h}, 75%, 68%)`,\n        highlight: `hsl(${h}, 85%, 82%)`,\n        badge: 'bg-white/10 text-white border-white/20'\n      };\n    }\n\n    // --- BUILT-IN DEMO DATASET ---\n    const DEMO_DATASET = {\n      entities: [\n        { id: \"e1\", name: \"TokenVault\", type: \"component\", aliases: [\"Vault\", \"KeyVault\"], metadata: { language: \"TypeScript\" } },\n        { id: \"e2\", name: \"AES-256-GCM\", type: \"technology\", aliases: [\"AES-GCM\"], metadata: { key_bits: 256 } },\n        { id: \"e3\", name: \"PBKDF2\", type: \"technology\", aliases: [\"KeyDerivation\"], metadata: { rounds: 100000 } },\n        { id: \"e4\", name: \"OAuth\", type: \"concept\", aliases: [\"OAuth2\"], metadata: { rfc: \"RFC 6749\" } },\n        { id: \"e5\", name: \"Supabase Edge Functions\", type: \"system\", aliases: [\"Deno Edge\"], metadata: { provider: \"Supabase\" } },\n        { id: \"e6\", name: \"pgvector\", type: \"technology\", aliases: [\"embeddings-store\"], metadata: { index: \"HNSW\" } },\n        { id: \"e7\", name: \"Google Gemini Embeddings\", type: \"system\", aliases: [\"gemini-embedding-001\"], metadata: { dimensions: 768 } },\n        { id: \"e8\", name: \"Raymond Memory Server\", type: \"component\", aliases: [\"Raymond\", \"RaymondMemorySystem\"], metadata: { version: \"1.1.0\" } },\n        { id: \"e9\", name: \"Antigravity Coordinator\", type: \"agent\", aliases: [\"Coordinator\"], metadata: { role: \"fleet-lead\" } },\n        { id: \"e10\", name: \"Coder Agent\", type: \"agent\", aliases: [\"coder_agent\"], metadata: { role: \"implementation\" } },\n        { id: \"e11\", name: \"SVGnest\", type: \"technology\", aliases: [\"svgnest\"], metadata: { purpose: \"2D nesting\" } },\n        { id: \"e12\", name: \"ConvexHull\", type: \"algorithm\", aliases: [\"MonotoneChain\"], metadata: { complexity: \"O(N log N)\" } },\n      ],\n      relations: [\n        { id: \"r1\", src: \"e1\", dst: \"e2\", predicate: \"uses\", valid_from: \"2026-11-15T12:00:00Z\", valid_to: null, memory_id: \"m1\" },\n        { id: \"r2\", src: \"e1\", dst: \"e3\", predicate: \"uses\", valid_from: \"2026-11-15T12:00:00Z\", valid_to: null, memory_id: \"m1\" },\n        { id: \"r3\", src: \"e1\", dst: \"e4\", predicate: \"protects\", valid_from: \"2026-11-15T12:00:00Z\", valid_to: null, memory_id: \"m1\" },\n        { id: \"r4\", src: \"e8\", dst: \"e5\", predicate: \"runs_on\", valid_from: \"2026-11-15T14:00:00Z\", valid_to: null, memory_id: \"m2\" },\n        { id: \"r5\", src: \"e8\", dst: \"e6\", predicate: \"stores_in\", valid_from: \"2026-11-15T14:00:00Z\", valid_to: null, memory_id: \"m2\" },\n        { id: \"r6\", src: \"e8\", dst: \"e7\", predicate: \"queries\", valid_from: \"2026-11-15T14:00:00Z\", valid_to: null, memory_id: \"m2\" },\n        { id: \"r7\", src: \"e11\", dst: \"e12\", predicate: \"accelerated_by\", valid_from: \"2026-11-19T18:31:00Z\", valid_to: null, memory_id: \"m3\" },\n      ],\n      memories: [\n        {\n          id: \"m1\",\n          agent_id: \"coder_agent\",\n          session_id: \"session_sec_audit\",\n          category: \"decision\",\n          content: \"TokenVault requires AES-256-GCM encryption with PBKDF2 key derivation for OAuth tokens to satisfy security compliance.\",\n          tags: [\"security\", \"oauth\", \"crypto\"],\n          created_at: \"2026-11-15T12:00:00Z\"\n        },\n        {\n          id: \"m2\",\n          agent_id: \"antigravity_lead\",\n          session_id: \"arch_review\",\n          category: \"fact\",\n          content: \"Raymond Edge memory server deployed onto Supabase Edge Runtime (Deno), connecting to pgvector with HNSW index and Gemini 768-dim embeddings.\",\n          tags: [\"architecture\", \"supabase\", \"pgvector\"],\n          created_at: \"2026-11-15T14:00:00Z\"\n        },\n        {\n          id: \"m3\",\n          agent_id: \"antigravity\",\n          session_id: \"amr-prepress\",\n          category: \"decision\",\n          content: \"Tool Architecture: 2D Shape Nesting with Convex Hull Proxy and SVGnest. Accelerates Minkowski sum from O(N*M) to O(N+M) and eliminates concave interlock.\",\n          tags: [\"nesting\", \"svgnest\", \"convex-hull\"],\n          created_at: \"2026-11-19T18:31:00Z\"\n        },\n        {\n          id: \"m4\",\n          agent_id: \"antigravity\",\n          session_id: \"fleet_preferences\",\n          category: \"preference\",\n          content: \"Always use internal interactive Knowledge Graph viewer over static charts when exploring entity topologies and memories.\",\n          tags: [\"preferences\", \"viewer\", \"ui\"],\n          created_at: \"2026-11-19T21:00:00Z\"\n        }\n      ],\n      memory_entities: [\n        { memory_id: \"m1\", entity_id: \"e1\" },\n        { memory_id: \"m1\", entity_id: \"e2\" },\n        { memory_id: \"m2\", entity_id: \"e8\" },\n        { memory_id: \"m3\", entity_id: \"e11\" },\n        { memory_id: \"m3\", entity_id: \"e12\" }\n      ]\n    };\n\n    // --- INITIALIZATION ---\n    window.addEventListener('DOMContentLoaded', () => {\n      lucide.createIcons();\n      initNetwork();\n      loadStoredCredentials();\n      autoConnectOrDemo();\n    });\n\n    function loadStoredCredentials() {\n      const urlParams = new URLSearchParams(window.location.search);\n      const urlParam = urlParams.get('supabaseUrl') || urlParams.get('url');\n      const keyParam = urlParams.get('supabaseKey') || urlParams.get('key') || urlParams.get('apikey');\n\n      const savedUrl = urlParam || localStorage.getItem('raymond_supabase_url') || (window.__DEFAULT_SUPABASE_URL__ || '');\n      const savedKey = keyParam || localStorage.getItem('raymond_supabase_key') || (window.__DEFAULT_SUPABASE_KEY__ || '');\n\n      document.getElementById('cfgSupabaseUrl').value = savedUrl;\n      document.getElementById('cfgSupabaseKey').value = savedKey;\n    }\n\n    async function autoConnectOrDemo() {\n      // 1. Check local proxy tool (/api/graph) only if not running from file://\n      if (window.location.protocol !== 'file:') {\n        try {\n          const proxyRes = await fetch('/api/graph');\n          if (proxyRes.ok) {\n            const graphJson = await proxyRes.json();\n            if (graphJson && graphJson.entities) {\n              applyGraphJson(graphJson, 'Live Edge Proxy');\n              return;\n            }\n          }\n        } catch (_) {}\n      }\n\n      // 2. Try configured credentials\n      const url = document.getElementById('cfgSupabaseUrl').value.trim();\n      const key = document.getElementById('cfgSupabaseKey').value.trim();\n\n      if (url && key) {\n        try {\n          await fetchFromSupabase(url, key);\n          return;\n        } catch (e) {\n          console.warn(\"Auto-connect failed:\", e);\n        }\n      }\n\n      // 3. Unauthenticated / No credentials configured:\n      // Do NOT auto-load demo data. Render empty canvas and set disconnected badge.\n      updateStatusBadge('disconnected', 'Not Connected');\n      renderGraph();\n    }\n\n    // --- PURE CLIENT OFFLINE IMPORT & DRAG-AND-DROP ---\n    function triggerJsonImport() {\n      document.getElementById('jsonFileInput').click();\n    }\n\n    function handleFileImport(e) {\n      const file = e.target.files && e.target.files[0];\n      if (!file) return;\n      loadGraphFromFile(file);\n      e.target.value = '';\n    }\n\n    function loadGraphFromFile(file) {\n      const reader = new FileReader();\n      reader.onload = (event) => {\n        try {\n          const data = JSON.parse(event.target.result);\n          if (data && (data.entities || data.nodes)) {\n            applyGraphJson(data, `File: ${file.name}`);\n            showToast(`Loaded graph from <b>${escapeHtml(file.name)}</b>`, 'success');\n          } else {\n            alert(\"Invalid Graph JSON structure. Expected JSON with an 'entities' array.\");\n          }\n        } catch (err) {\n          alert(\"Error parsing JSON file: \" + err.message);\n        }\n      };\n      reader.readAsText(file);\n    }\n\n    window.addEventListener('dragover', (e) => {\n      e.preventDefault();\n      e.stopPropagation();\n    });\n\n    window.addEventListener('drop', (e) => {\n      e.preventDefault();\n      e.stopPropagation();\n      if (e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files.length > 0) {\n        const file = e.dataTransfer.files[0];\n        if (file.name.toLowerCase().endsWith('.json')) {\n          loadGraphFromFile(file);\n        }\n      }\n    });\n\n    function applyGraphJson(graphJson, sourceLabel = 'Live Proxy') {\n      rawEntities = graphJson.entities || [];\n      rawRelations = graphJson.relations || [];\n      rawMemories = graphJson.memories || [];\n      rawMemoryEntities = graphJson.memory_entities || [];\n\n      updateStatusBadge('connected', sourceLabel);\n      closeSettingsModal();\n      renderGraph();\n      setTimeout(fitGraph, 300);\n    }\n\n    // --- VIS NETWORK SETUP ---\n    function initNetwork() {\n      const container = document.getElementById('graphContainer');\n      const data = { nodes: new vis.DataSet([]), edges: new vis.DataSet([]) };\n\n      const options = {\n        nodes: {\n          shape: 'dot',\n          size: 18,\n          font: {\n            size: 13,\n            color: '#F8FAFC',\n            face: 'Plus Jakarta Sans, sans-serif',\n            strokeWidth: 3,\n            strokeColor: '#090d16'\n          },\n          borderWidth: 2,\n          shadow: {\n            enabled: true,\n            color: 'rgba(0, 0, 0, 0.7)',\n            size: 12,\n            x: 0,\n            y: 2\n          }\n        },\n        edges: {\n          arrows: {\n            to: { enabled: true, scaleFactor: 0.8 }\n          },\n          font: {\n            size: 10,\n            color: '#94A3B8',\n            face: 'JetBrains Mono, monospace',\n            strokeWidth: 3,\n            strokeColor: '#090d16',\n            align: 'middle'\n          },\n          color: {\n            color: 'rgba(255, 255, 255, 0.25)',\n            highlight: '#38BDF8',\n            hover: '#64748B'\n          },\n          smooth: {\n            enabled: true,\n            type: 'cubicBezier',\n            roundness: 0.2\n          }\n        },\n        physics: {\n          enabled: isPhysicsActive,\n          solver: 'forceAtlas2Based',\n          forceAtlas2Based: {\n            gravitationalConstant: -70,\n            centralGravity: 0.01,\n            springLength: 130,\n            springConstant: 0.08,\n            damping: 0.7,\n            avoidOverlap: 0.8\n          },\n          stabilization: {\n            iterations: 140,\n            updateInterval: 25\n          }\n        },\n        interaction: {\n          hover: true,\n          tooltipDelay: 120,\n          hideEdgesOnDrag: false,\n          multiselect: false,\n          navigationButtons: true,\n          keyboard: false\n        }\n      };\n\n      network = new vis.Network(container, data, options);\n\n      network.on('click', onGraphClick);\n      network.on('doubleClick', onGraphDoubleClick);\n      network.on('hoverNode', () => { container.style.cursor = 'pointer'; });\n      network.on('blurNode', () => { container.style.cursor = 'default'; });\n\n      // Drag-to-Connect Interaction: Drag node onto another to create 'connected_to'\n      let draggedNodeId = null;\n      let hoverTargetNodeId = null;\n\n      network.on('dragStart', (params) => {\n        if (params.nodes && params.nodes.length > 0) {\n          draggedNodeId = params.nodes[0];\n          // Freeze layout physics while dragging so nodes don't chase or repel each other\n          network.setOptions({ physics: { enabled: false } });\n        } else {\n          draggedNodeId = null;\n        }\n        hoverTargetNodeId = null;\n      });\n\n      network.on('dragging', (params) => {\n        if (!draggedNodeId) return;\n\n        const pointerCanvas = params.pointer.canvas;\n        const allPositions = network.getPositions();\n        let closestId = null;\n        let minDist = Infinity;\n\n        for (const [id, pos] of Object.entries(allPositions)) {\n          if (id === draggedNodeId) continue;\n          const d = Math.hypot(pos.x - pointerCanvas.x, pos.y - pointerCanvas.y);\n          if (d < minDist) {\n            minDist = d;\n            closestId = id;\n          }\n        }\n\n        const pill = document.getElementById('dropConnectPill');\n        const pillText = document.getElementById('dropConnectPillText');\n        if (closestId && minDist <= 55) {\n          hoverTargetNodeId = closestId;\n          const targetName = getNodeDisplayName(closestId);\n          pillText.innerHTML = `Drop on <b>${escapeHtml(targetName)}</b> to create <code class=\"font-mono bg-emerald-950/80 px-1 py-0.5 rounded text-emerald-200\">connected_to</code>`;\n          pill.style.left = `${params.pointer.DOM.x + 18}px`;\n          pill.style.top = `${params.pointer.DOM.y - 14}px`;\n          pill.classList.remove('hidden');\n          container.style.cursor = 'copy';\n        } else {\n          hoverTargetNodeId = null;\n          pill.classList.add('hidden');\n          container.style.cursor = 'pointer';\n        }\n      });\n\n      network.on('dragEnd', (params) => {\n        const pill = document.getElementById('dropConnectPill');\n        pill.classList.add('hidden');\n        container.style.cursor = 'default';\n\n        const srcId = draggedNodeId;\n        let dstId = hoverTargetNodeId;\n\n        // Fallback distance check at drop position\n        if (srcId && !dstId && params.pointer && params.pointer.canvas) {\n          const pointerCanvas = params.pointer.canvas;\n          const allPositions = network.getPositions();\n          let closestId = null;\n          let minDist = Infinity;\n          for (const [id, pos] of Object.entries(allPositions)) {\n            if (id === srcId) continue;\n            const d = Math.hypot(pos.x - pointerCanvas.x, pos.y - pointerCanvas.y);\n            if (d < minDist) {\n              minDist = d;\n              closestId = id;\n            }\n          }\n          if (closestId && minDist <= 55) {\n            dstId = closestId;\n          }\n        }\n\n        draggedNodeId = null;\n        hoverTargetNodeId = null;\n\n        if (srcId && dstId && srcId !== dstId) {\n          handleDropConnect(srcId, dstId);\n        }\n\n        // Restore physics if user had physics active\n        if (isPhysicsActive) {\n          network.setOptions({ physics: { enabled: true } });\n        }\n      });\n    }\n\n    // --- UNLINKED MEMORY EXTRACTION ---\n    function getMemoryLabel(m) {\n      if (m.metadata && (m.metadata.title || m.metadata.name)) {\n        return m.metadata.title || m.metadata.name;\n      }\n      const firstLine = (m.content || '').split('\\n').find(l => l.trim().length > 0) || '';\n      const cleaned = firstLine.replace(/^[#*\\-\\d.\\s]+/, '').trim();\n      if (cleaned.length <= 28) return cleaned || `Memory (${m.category || 'general'})`;\n      return cleaned.slice(0, 26) + '\u2026';\n    }\n\n    function getUnlinkedMemoryEntities() {\n      const linkedMemIds = new Set();\n      const existingEntityIds = new Set(rawEntities.map(e => e.id));\n      rawMemoryEntities.forEach(me => {\n        if (me.memory_id && existingEntityIds.has(me.entity_id)) linkedMemIds.add(me.memory_id);\n      });\n      rawRelations.forEach(r => {\n        if (r.memory_id) linkedMemIds.add(r.memory_id);\n      });\n\n      return rawMemories.filter(m => !linkedMemIds.has(m.id)).map(m => ({\n        id: m.id,\n        name: getMemoryLabel(m),\n        type: 'memory',\n        aliases: m.tags || [],\n        metadata: {\n          ...m.metadata,\n          memory_id: m.id,\n          category: m.category,\n          agent_id: m.agent_id,\n          session_id: m.session_id,\n          created_at: m.created_at,\n          full_content: m.content,\n          is_unlinked_memory: true\n        },\n        isMemoryNode: true,\n        rawMemory: m\n      }));\n    }\n\n    // --- DRAG-TO-CONNECT RELATION CREATION ---\n    function getNodeDisplayName(nodeId) {\n      const ent = rawEntities.find(e => e.id === nodeId);\n      if (ent) return ent.name;\n      const unlinked = getUnlinkedMemoryEntities();\n      const mem = unlinked.find(e => e.id === nodeId);\n      if (mem) return mem.name;\n      return nodeId;\n    }\n\n    async function handleDropConnect(srcId, dstId) {\n      // 1. Prevent connecting identical nodes\n      if (srcId === dstId) return;\n\n      // 2. Check if relation already exists with predicate connected_to\n      const existing = rawRelations.find(r => \n        (!r.valid_to) && \n        ((r.src === srcId && r.dst === dstId) || (r.src === dstId && r.dst === srcId)) && \n        r.predicate === 'connected_to'\n      );\n      if (existing) {\n        showToast('Nodes are already linked with \"connected_to\"', 'info');\n        return;\n      }\n\n      const srcName = getNodeDisplayName(srcId);\n      const dstName = getNodeDisplayName(dstId);\n\n      // 3. Handle promote if either node is an unlinked memory node\n      const unlinked = getUnlinkedMemoryEntities();\n      const srcMem = unlinked.find(e => e.id === srcId);\n      const dstMem = unlinked.find(e => e.id === dstId);\n\n      if (srcMem && !rawEntities.find(e => e.id === srcId)) {\n        await promoteMemoryToEntity(srcMem);\n      }\n      if (dstMem && !rawEntities.find(e => e.id === dstId)) {\n        await promoteMemoryToEntity(dstMem);\n      }\n\n      // 4. Create new relation\n      const relId = 'rel_' + Date.now() + '_' + Math.random().toString(36).slice(2, 6);\n      const newRel = {\n        id: relId,\n        src: srcId,\n        dst: dstId,\n        predicate: 'connected_to',\n        valid_from: new Date().toISOString(),\n        valid_to: null,\n        metadata: {\n          created_via: 'drag_and_drop',\n          created_at: new Date().toISOString()\n        }\n      };\n\n      rawRelations.push(newRel);\n      renderGraph();\n\n      showToast(`Connected <b>${escapeHtml(srcName)}</b> \u2794 <code class=\"font-mono text-sky-400\">connected_to</code> \u2794 <b>${escapeHtml(dstName)}</b>`, 'success', {\n        label: 'Undo',\n        onClick: () => undoCreateRelation(newRel)\n      });\n\n      // 5. Asynchronously persist to backend (proxy or PostgREST direct)\n      persistRelationToBackend(newRel);\n    }\n\n    async function promoteMemoryToEntity(memNode) {\n      const rawMem = memNode.rawMemory || rawMemories.find(m => m.id === memNode.id);\n      const newEntity = {\n        id: memNode.id,\n        name: memNode.name,\n        type: (rawMem && rawMem.category) || 'concept',\n        aliases: (rawMem && rawMem.tags) || [],\n        metadata: {\n          ...(rawMem ? rawMem.metadata : {}),\n          grounded_memory_id: memNode.id,\n          promoted_via: 'drag_and_drop'\n        }\n      };\n\n      rawEntities.push(newEntity);\n      rawMemoryEntities.push({\n        memory_id: memNode.id,\n        entity_id: memNode.id\n      });\n\n      try {\n        const entityPayload = {\n          id: newEntity.id,\n          name: newEntity.name,\n          type: newEntity.type,\n          aliases: newEntity.aliases,\n          metadata: newEntity.metadata\n        };\n        const memEntPayload = {\n          memory_id: memNode.id,\n          entity_id: memNode.id\n        };\n\n        const res = await fetch('/api/entities', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify(entityPayload)\n        });\n\n        if (res.ok) {\n          await fetch('/api/memory_entities', {\n            method: 'POST',\n            headers: { 'Content-Type': 'application/json' },\n            body: JSON.stringify(memEntPayload)\n          });\n        } else {\n          const url = document.getElementById('cfgSupabaseUrl').value.trim();\n          const key = document.getElementById('cfgSupabaseKey').value.trim();\n          if (url && key) {\n            const cleanUrl = url.replace(/\\/+$/, '');\n            const headers = {\n              'apikey': key,\n              'Authorization': `Bearer ${key}`,\n              'Content-Type': 'application/json',\n              'Prefer': 'return=representation'\n            };\n            await fetch(`${cleanUrl}/rest/v1/entities`, {\n              method: 'POST',\n              headers,\n              body: JSON.stringify(entityPayload)\n            });\n            await fetch(`${cleanUrl}/rest/v1/memory_entities`, {\n              method: 'POST',\n              headers,\n              body: JSON.stringify(memEntPayload)\n            });\n          }\n        }\n      } catch (e) {\n        console.warn('Failed to persist promoted entity:', e);\n      }\n    }\n\n    async function persistRelationToBackend(relObj) {\n      try {\n        const payload = {\n          src: relObj.src,\n          dst: relObj.dst,\n          predicate: relObj.predicate,\n          valid_from: relObj.valid_from,\n          metadata: relObj.metadata\n        };\n\n        const proxyRes = await fetch('/api/relations', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify(payload)\n        });\n\n        if (proxyRes.ok) {\n          const resData = await proxyRes.json();\n          if (resData.data && resData.data.id) {\n            relObj.id = resData.data.id;\n          }\n          return;\n        }\n\n        const url = document.getElementById('cfgSupabaseUrl').value.trim();\n        const key = document.getElementById('cfgSupabaseKey').value.trim();\n        if (url && key) {\n          const cleanUrl = url.replace(/\\/+$/, '');\n          const headers = {\n            'apikey': key,\n            'Authorization': `Bearer ${key}`,\n            'Content-Type': 'application/json',\n            'Prefer': 'return=representation'\n          };\n          const sbRes = await fetch(`${cleanUrl}/rest/v1/relations`, {\n            method: 'POST',\n            headers,\n            body: JSON.stringify(payload)\n          });\n          if (sbRes.ok) {\n            const data = await sbRes.json();\n            if (data && data[0] && data[0].id) {\n              relObj.id = data[0].id;\n            }\n          }\n        }\n      } catch (err) {\n        console.warn('Failed to persist relation:', err);\n      }\n    }\n\n    async function undoCreateRelation(relObj) {\n      const idx = rawRelations.findIndex(r => r.id === relObj.id);\n      if (idx !== -1) {\n        rawRelations.splice(idx, 1);\n        renderGraph();\n      }\n\n      showToast('Undid \"connected_to\" relation', 'info');\n\n      try {\n        const proxyRes = await fetch(`/api/relations?id=${relObj.id}`, { method: 'DELETE' });\n        if (!proxyRes.ok) {\n          const url = document.getElementById('cfgSupabaseUrl').value.trim();\n          const key = document.getElementById('cfgSupabaseKey').value.trim();\n          if (url && key) {\n            const cleanUrl = url.replace(/\\/+$/, '');\n            await fetch(`${cleanUrl}/rest/v1/relations?id=eq.${relObj.id}`, {\n              method: 'DELETE',\n              headers: {\n                'apikey': key,\n                'Authorization': `Bearer ${key}`\n              }\n            });\n          }\n        }\n      } catch (e) {\n        console.warn('Error deleting relation during undo:', e);\n      }\n    }\n\n    function showToast(msg, type = 'info', action = null) {\n      const container = document.getElementById('toastContainer');\n      if (!container) return;\n\n      const toast = document.createElement('div');\n      const isSuccess = type === 'success';\n      toast.className = `pointer-events-auto flex items-center gap-3 px-4 py-2.5 rounded-2xl shadow-2xl backdrop-blur-xl border text-xs text-white transition-all transform duration-300 translate-y-4 opacity-0 ${\n        isSuccess ? 'bg-dark-900/95 border-emerald-500/40 shadow-emerald-950/50' : 'bg-dark-900/95 border-sky-500/40 shadow-sky-950/50'\n      }`;\n\n      let actionHtml = '';\n      if (action) {\n        actionHtml = `<button id=\"toastActionBtn\" class=\"ml-2 font-bold px-2.5 py-1 rounded-lg bg-white/10 hover:bg-white/20 text-emerald-300 hover:text-white transition\">${escapeHtml(action.label || 'Action')}</button>`;\n      }\n\n      toast.innerHTML = `\n        <div class=\"flex items-center gap-2\">\n          <i data-lucide=\"${isSuccess ? 'check-circle-2' : 'info'}\" class=\"w-4 h-4 ${isSuccess ? 'text-emerald-400' : 'text-sky-400'} shrink-0\"></i>\n          <span class=\"leading-snug\">${msg}</span>\n        </div>\n        ${actionHtml}\n      `;\n\n      container.appendChild(toast);\n      lucide.createIcons();\n\n      if (action) {\n        const btn = toast.querySelector('#toastActionBtn');\n        if (btn) {\n          btn.onclick = () => {\n            action.onClick();\n            toast.remove();\n          };\n        }\n      }\n\n      requestAnimationFrame(() => {\n        toast.classList.remove('translate-y-4', 'opacity-0');\n      });\n\n      setTimeout(() => {\n        toast.classList.add('translate-y-4', 'opacity-0');\n        setTimeout(() => toast.remove(), 300);\n      }, 5500);\n    }\n\n    // --- DATA RENDERING & FILTERING ---\n    function renderGraph() {\n      if (!network) return;\n\n      const unlinkedEntities = getUnlinkedMemoryEntities();\n      const allGraphNodes = [...rawEntities, ...unlinkedEntities];\n\n      // Empty State Overlay Visibility\n      const emptyOverlay = document.getElementById('emptyStateOverlay');\n      if (emptyOverlay) {\n        if (allGraphNodes.length === 0) {\n          emptyOverlay.classList.remove('hidden');\n          lucide.createIcons();\n        } else {\n          emptyOverlay.classList.add('hidden');\n        }\n      }\n\n      // 1. Determine active entity set based on Hop Focus Mode\n      let allowedEntityIds = null;\n      if (focusCenterEntityId) {\n        allowedEntityIds = computeHopNeighborhood(focusCenterEntityId, focusHopDepth || 1);\n        document.getElementById('focusModeBox').classList.remove('hidden');\n        const center = allGraphNodes.find(e => e.id === focusCenterEntityId);\n        document.getElementById('focusEntityName').textContent = center ? center.name : focusCenterEntityId;\n      } else {\n        document.getElementById('focusModeBox').classList.add('hidden');\n      }\n\n      // 2. Filter Entities by active Entity Type filters and Hop Neighborhood\n      const filteredEntities = allGraphNodes.filter(ent => {\n        if (allowedEntityIds && !allowedEntityIds.has(ent.id)) return false;\n        if (activeTypeFilters.size > 0 && !activeTypeFilters.has(ent.type?.toLowerCase())) return false;\n        return true;\n      });\n\n      const visibleEntityIds = new Set(filteredEntities.map(e => e.id));\n\n      // 3. Filter Relations\n      let supersededCount = 0;\n      const filteredRelations = rawRelations.filter(rel => {\n        const isSuperseded = Boolean(rel.valid_to);\n        if (isSuperseded) supersededCount++;\n\n        if (!showSuperseded && isSuperseded) return false;\n        if (!visibleEntityIds.has(rel.src) || !visibleEntityIds.has(rel.dst)) return false;\n        return true;\n      });\n\n      document.getElementById('supersededCountPill').textContent = supersededCount;\n\n      // 4. Compute topology degree for dynamic node sizing (no hardcoded hubs)\n      const degreeMap = new Map();\n      rawRelations.forEach(r => {\n        if (!r.valid_to || showSuperseded) {\n          degreeMap.set(r.src, (degreeMap.get(r.src) || 0) + 1);\n          degreeMap.set(r.dst, (degreeMap.get(r.dst) || 0) + 1);\n        }\n      });\n\n      // 5. Build vis.DataSet items with glow shadows & degree-based sizing\n      const nodeItems = filteredEntities.map(ent => {\n        const style = getTypeStyle(ent.type);\n        const deg = degreeMap.get(ent.id) || 0;\n        const size = ent.isMemoryNode ? 16 : Math.min(30, Math.max(16, 16 + deg * 1.6));\n        const isProminent = !ent.isMemoryNode && deg >= 4;\n        const aliases = (ent.aliases && ent.aliases.length > 0) ? `\\nAliases: ${ent.aliases.join(', ')}` : '';\n        const titleText = ent.isMemoryNode\n          ? `[UNLINKED MEMORY: ${(ent.metadata.category || 'general').toUpperCase()}]\\nAuthor: ${ent.metadata.agent_id || 'system'}\\nCreated: ${formatDate(ent.metadata.created_at)}\\nTags: ${(ent.aliases || []).join(', ') || 'none'}\\n\\n${(ent.metadata.full_content || '').slice(0, 180)}...`\n          : `[${ent.type?.toUpperCase() || 'CONCEPT'}] ${ent.name}${aliases}\\nConnections: ${deg}`;\n\n        return {\n          id: ent.id,\n          label: ent.name,\n          shape: 'dot',\n          size: size,\n          font: {\n            size: isProminent ? 14 : (ent.isMemoryNode ? 11 : 12),\n            face: 'Plus Jakarta Sans, sans-serif',\n            strokeWidth: 3,\n            strokeColor: '#090d16',\n            color: ent.isMemoryNode ? '#CBD5E1' : '#ffffff'\n          },\n          title: titleText,\n          color: {\n            background: style.bg,\n            border: style.border,\n            highlight: {\n              background: style.highlight,\n              border: '#FFFFFF'\n            }\n          },\n          shadow: {\n            enabled: true,\n            color: style.bg,\n            size: isProminent ? 22 : 10,\n            x: 0,\n            y: 0\n          }\n        };\n      });\n\n      const edgeItems = filteredRelations.map(rel => {\n        const isSuperseded = Boolean(rel.valid_to);\n        return {\n          id: rel.id,\n          from: rel.src,\n          to: rel.dst,\n          label: rel.predicate,\n          dashes: isSuperseded ? [5, 5] : false,\n          color: {\n            color: isSuperseded ? '#EF4444' : 'rgba(255, 255, 255, 0.3)',\n            highlight: isSuperseded ? '#F87171' : '#38BDF8',\n            opacity: isSuperseded ? 0.45 : 0.95\n          },\n          font: {\n            color: isSuperseded ? '#FCA5A5' : '#94A3B8',\n            face: 'JetBrains Mono, monospace',\n            size: 10,\n            strokeColor: '#090d16',\n            strokeWidth: 3\n          },\n          title: `Predicate: ${rel.predicate}\\nFrom: ${rel.valid_from || 'unknown'}${rel.valid_to ? `\\nSuperseded: ${rel.valid_to}` : ' (Active)'}`\n        };\n      });\n\n      network.setData({\n        nodes: new vis.DataSet(nodeItems),\n        edges: new vis.DataSet(edgeItems)\n      });\n\n      // Update Header Stats\n      document.getElementById('statEntities').textContent = rawEntities.length;\n      document.getElementById('statRelations').textContent = rawRelations.filter(r => !r.valid_to).length;\n      const memStatElem = document.getElementById('statMemories');\n      if (unlinkedEntities.length > 0) {\n        memStatElem.innerHTML = `${rawMemories.length} <span class=\"text-slate-400 text-[10px] font-normal\">(${unlinkedEntities.length} unlinked)</span>`;\n      } else {\n        memStatElem.textContent = rawMemories.length;\n      }\n\n      renderFilterPills();\n    }\n\n    function computeHopNeighborhood(centerId, maxHops = 1) {\n      const visited = new Set([centerId]);\n      let currentBorder = new Set([centerId]);\n\n      for (let hop = 0; hop < maxHops; hop++) {\n        const nextBorder = new Set();\n        for (const rel of rawRelations) {\n          if (!showSuperseded && rel.valid_to) continue;\n\n          if (currentBorder.has(rel.src) && !visited.has(rel.dst)) {\n            visited.add(rel.dst);\n            nextBorder.add(rel.dst);\n          }\n          if (currentBorder.has(rel.dst) && !visited.has(rel.src)) {\n            visited.add(rel.src);\n            nextBorder.add(rel.src);\n          }\n        }\n        currentBorder = nextBorder;\n        if (currentBorder.size === 0) break;\n      }\n      return visited;\n    }\n\n    function renderFilterPills() {\n      const container = document.getElementById('typeFilterPills');\n      container.innerHTML = '';\n\n      const counts = {};\n      const unlinkedEntities = getUnlinkedMemoryEntities();\n      [...rawEntities, ...unlinkedEntities].forEach(e => {\n        const t = (e.type || 'concept').toLowerCase();\n        counts[t] = (counts[t] || 0) + 1;\n      });\n\n      Object.entries(counts).forEach(([type, count]) => {\n        const style = getTypeStyle(type);\n        const isActive = activeTypeFilters.size === 0 || activeTypeFilters.has(type);\n        \n        const pill = document.createElement('button');\n        pill.className = `px-2 py-0.5 rounded-full text-[10px] font-semibold border transition flex items-center gap-1.5 ${\n          isActive \n            ? `${style.badge} ring-1 ring-white/20 shadow-sm` \n            : 'bg-dark-800 text-slate-500 border-slate-700/60 opacity-60'\n        }`;\n        \n        pill.innerHTML = `\n          <span class=\"w-1.5 h-1.5 rounded-full\" style=\"background-color: ${style.bg}\"></span>\n          <span>${type}</span>\n          <span class=\"opacity-70 font-mono\">(${count})</span>\n        `;\n\n        pill.onclick = () => {\n          if (activeTypeFilters.has(type)) {\n            activeTypeFilters.delete(type);\n          } else {\n            activeTypeFilters.add(type);\n          }\n          renderGraph();\n        };\n\n        container.appendChild(pill);\n      });\n    }\n\n    function resetFilters() {\n      activeTypeFilters.clear();\n      showSuperseded = false;\n      document.getElementById('chkShowSuperseded').checked = false;\n      focusCenterEntityId = null;\n      renderGraph();\n      fitGraph();\n    }\n\n    function toggleSuperseded(checked) {\n      showSuperseded = checked;\n      renderGraph();\n    }\n\n    // --- GRAPH CLICK & SELECTION ---\n    function onGraphClick(params) {\n      if (params.nodes && params.nodes.length > 0) {\n        const nodeId = params.nodes[0];\n        inspectEntity(nodeId);\n      } else if (params.edges && params.edges.length > 0) {\n        const edgeId = params.edges[0];\n        inspectRelation(edgeId);\n      } else {\n        closeInspector();\n      }\n    }\n\n    function onGraphDoubleClick(params) {\n      if (params.nodes && params.nodes.length > 0) {\n        const nodeId = params.nodes[0];\n        focusCenterEntityId = (focusCenterEntityId === nodeId) ? null : nodeId;\n        focusHopDepth = 1;\n        renderGraph();\n        network.focus(nodeId, { scale: 1.2, animation: { duration: 500, easingFunction: 'easeInOutQuad' } });\n      }\n    }\n\n    function clearFocusMode() {\n      focusCenterEntityId = null;\n      renderGraph();\n      fitGraph();\n    }\n\n    // --- INSPECTOR DRAWER ---\n    function inspectEntity(entityId) {\n      selectedEntityId = entityId;\n      const unlinkedEntities = getUnlinkedMemoryEntities();\n      const entity = [...rawEntities, ...unlinkedEntities].find(e => e.id === entityId);\n      if (!entity) return;\n\n      const style = getTypeStyle(entity.type);\n      const drawer = document.getElementById('inspectorDrawer');\n      const title = document.getElementById('inspectorTitle');\n      const content = document.getElementById('inspectorContent');\n\n      title.textContent = entity.name;\n      drawer.classList.remove('translate-x-full');\n\n      // Check if this is an unlinked memory node\n      if (entity.isMemoryNode && entity.rawMemory) {\n        renderUnlinkedMemoryInspector(entity, content, style);\n        lucide.createIcons();\n        return;\n      }\n\n      // Relations\n      const outRels = rawRelations.filter(r => r.src === entityId);\n      const inRels = rawRelations.filter(r => r.dst === entityId);\n\n      // Grounded Memories\n      const groundedMemIds = new Set(\n        rawMemoryEntities.filter(me => me.entity_id === entityId).map(me => me.memory_id)\n      );\n      outRels.concat(inRels).forEach(r => { if (r.memory_id) groundedMemIds.add(r.memory_id); });\n      const memories = rawMemories.filter(m => groundedMemIds.has(m.id));\n\n      let aliasesHtml = '';\n      if (entity.aliases && entity.aliases.length > 0) {\n        aliasesHtml = `\n          <div class=\"mt-2 flex flex-wrap gap-1\">\n            ${entity.aliases.map(a => `<span class=\"px-2 py-0.5 rounded-lg bg-white/5 text-slate-300 border border-white/10 font-mono text-[10px]\">${escapeHtml(a)}</span>`).join('')}\n          </div>\n        `;\n      }\n\n      let metadataHtml = '';\n      if (entity.metadata && Object.keys(entity.metadata).length > 0) {\n        metadataHtml = `\n          <div class=\"space-y-1\">\n            <span class=\"text-[11px] font-bold text-slate-400 uppercase tracking-wider\">Metadata</span>\n            <pre class=\"p-3 rounded-xl bg-black/40 border border-white/10 font-mono text-[11px] text-slate-300 overflow-x-auto\">${escapeHtml(JSON.stringify(entity.metadata, null, 2))}</pre>\n          </div>\n        `;\n      }\n\n      // Outbound Relations List with Modern Directional Cards\n      let outRelsHtml = outRels.length === 0 ? '<div class=\"text-slate-500 italic text-[11px]\">None</div>' : outRels.map(r => {\n        const target = rawEntities.find(e => e.id === r.dst);\n        const isSup = Boolean(r.valid_to);\n        return `\n          <div class=\"p-2.5 rounded-xl bg-white/5 hover:bg-white/10 border border-white/5 hover:border-white/15 transition transform hover:translate-x-1 flex items-center justify-between\">\n            <div class=\"flex items-center gap-2 overflow-hidden\">\n              <span class=\"text-slate-400\">\u2794</span>\n              <span class=\"font-mono text-[10px] bg-white/10 px-2 py-0.5 rounded text-sky-400 border border-white/10 font-semibold\">${escapeHtml(r.predicate)}</span>\n              <button onclick=\"focusAndInspectNode('${r.dst}')\" class=\"text-white hover:text-purple-300 font-bold truncate underline underline-offset-2\">\n                ${escapeHtml(target ? target.name : r.dst)}\n              </button>\n            </div>\n            ${isSup ? '<span class=\"text-[9px] px-1.5 py-0.5 rounded bg-red-950/80 text-red-400 border border-red-800\">superseded</span>' : '<span class=\"text-[9px] px-1.5 py-0.5 rounded bg-emerald-950/80 text-emerald-400 border border-emerald-800\">active</span>'}\n          </div>\n        `;\n      }).join('');\n\n      // Inbound Relations List\n      let inRelsHtml = inRels.length === 0 ? '<div class=\"text-slate-500 italic text-[11px]\">None</div>' : inRels.map(r => {\n        const source = rawEntities.find(e => e.id === r.src);\n        const isSup = Boolean(r.valid_to);\n        return `\n          <div class=\"p-2.5 rounded-xl bg-white/5 hover:bg-white/10 border border-white/5 hover:border-white/15 transition transform hover:translate-x-1 flex items-center justify-between\">\n            <div class=\"flex items-center gap-2 overflow-hidden\">\n              <span class=\"text-slate-400\">\ud83e\udc14</span>\n              <button onclick=\"focusAndInspectNode('${r.src}')\" class=\"text-white hover:text-purple-300 font-bold truncate underline underline-offset-2\">\n                ${escapeHtml(source ? source.name : r.src)}\n              </button>\n              <span class=\"font-mono text-[10px] bg-white/10 px-2 py-0.5 rounded text-emerald-400 border border-white/10 font-semibold\">${escapeHtml(r.predicate)}</span>\n            </div>\n            ${isSup ? '<span class=\"text-[9px] px-1.5 py-0.5 rounded bg-red-950/80 text-red-400 border border-red-800\">superseded</span>' : '<span class=\"text-[9px] px-1.5 py-0.5 rounded bg-emerald-950/80 text-emerald-400 border border-emerald-800\">active</span>'}\n          </div>\n        `;\n      }).join('');\n\n      // Grounded Memories HTML\n      let memoriesHtml = memories.length === 0 ? '<div class=\"text-slate-500 italic text-[11px]\">No grounded memories</div>' : memories.map(m => `\n        <div class=\"p-3.5 rounded-xl bg-purple-950/20 border border-purple-500/20 space-y-2.5 shadow-sm\">\n          <div class=\"flex items-center justify-between\">\n            <span class=\"px-2 py-0.5 rounded-full text-[10px] bg-purple-950 text-purple-300 border border-purple-800 font-semibold uppercase tracking-wider\">${escapeHtml(m.category || 'general')}</span>\n            <span class=\"text-[10px] text-slate-400 font-mono\">${formatDate(m.created_at)}</span>\n          </div>\n          <div class=\"prose-dark\">\n            ${renderMarkdown(m.content)}\n          </div>\n          <div class=\"flex items-center justify-between pt-2 border-t border-white/10 text-[10px] text-slate-400\">\n            <span class=\"font-mono text-purple-300 font-semibold\">\ud83d\udc64 ${escapeHtml(m.agent_id || 'system')}</span>\n            <div class=\"flex gap-1 flex-wrap\">\n              ${(m.tags || []).map(t => `<span class=\"text-slate-400 font-mono bg-white/5 px-1.5 py-0.5 rounded\">#${escapeHtml(t)}</span>`).join(' ')}\n            </div>\n          </div>\n        </div>\n      `).join('');\n\n      const entityDesc = entity.metadata?.description || entity.metadata?.summary || entity.metadata?.notes;\n      const descHtml = entityDesc ? `\n        <div class=\"p-3.5 rounded-xl bg-white/5 border border-white/10 space-y-1.5\">\n          <span class=\"text-[10px] font-bold text-slate-400 uppercase tracking-wider\">Description</span>\n          <div class=\"prose-dark\">\n            ${renderMarkdown(entityDesc)}\n          </div>\n        </div>\n      ` : '';\n\n      content.innerHTML = `\n        <!-- Entity Badge & Aliases -->\n        <div class=\"p-3.5 rounded-2xl bg-white/5 border border-white/10\">\n          <div class=\"flex items-center justify-between\">\n            <span class=\"text-[10px] font-bold text-slate-400 uppercase tracking-wider\">Entity Type</span>\n            <span class=\"px-2.5 py-0.5 rounded-full text-[11px] font-bold ${style.badge}\">\n              ${escapeHtml(entity.type || 'concept')}\n            </span>\n          </div>\n          ${aliasesHtml}\n          <div class=\"mt-3 pt-2.5 border-t border-white/10 flex justify-between text-[11px] text-slate-300\">\n            <div>Degree: <span class=\"text-white font-mono font-bold\">${outRels.length + inRels.length}</span></div>\n            <div>Grounded Memories: <span class=\"text-purple-400 font-mono font-bold\">${memories.length}</span></div>\n          </div>\n        </div>\n\n        ${descHtml}\n\n        <!-- Quick Neighborhood Action -->\n        <div class=\"flex gap-2\">\n          <button onclick=\"isolateEntityNeighborhood('${entity.id}')\" class=\"flex-1 py-2 px-3 bg-white/10 hover:bg-white/15 border border-white/15 rounded-xl text-purple-300 hover:text-white font-semibold transition text-center flex items-center justify-center gap-1.5 shadow-sm\">\n            <i data-lucide=\"crosshair\" class=\"w-3.5 h-3.5 text-purple-400\"></i> Isolate 1-Hop Neighborhood\n          </button>\n        </div>\n\n        ${metadataHtml}\n\n        <!-- Outgoing Relations -->\n        <div class=\"space-y-2\">\n          <span class=\"text-[11px] font-bold text-slate-400 uppercase tracking-wider flex items-center justify-between\">\n            <span>Outgoing Relations</span>\n            <span class=\"text-slate-500 font-mono\">(${outRels.length})</span>\n          </span>\n          <div class=\"space-y-1.5 max-h-48 overflow-y-auto pr-1\">\n            ${outRelsHtml}\n          </div>\n        </div>\n\n        <!-- Incoming Relations -->\n        <div class=\"space-y-2\">\n          <span class=\"text-[11px] font-bold text-slate-400 uppercase tracking-wider flex items-center justify-between\">\n            <span>Incoming Relations</span>\n            <span class=\"text-slate-500 font-mono\">(${inRels.length})</span>\n          </span>\n          <div class=\"space-y-1.5 max-h-48 overflow-y-auto pr-1\">\n            ${inRelsHtml}\n          </div>\n        </div>\n\n        <!-- Grounded Memories -->\n        <div class=\"space-y-2 pt-2 border-t border-white/10\">\n          <span class=\"text-[11px] font-bold text-slate-400 uppercase tracking-wider flex items-center justify-between\">\n            <span>Grounded Memories</span>\n            <span class=\"text-purple-400 font-mono font-bold\">(${memories.length})</span>\n          </span>\n          <div class=\"space-y-2 max-h-72 overflow-y-auto pr-1\">\n            ${memoriesHtml}\n          </div>\n        </div>\n      `;\n\n      lucide.createIcons();\n    }\n\n    function renderUnlinkedMemoryInspector(entity, content, style) {\n      const m = entity.rawMemory;\n      content.innerHTML = `\n        <!-- Unlinked Memory Status Card -->\n        <div class=\"p-3.5 rounded-2xl bg-slate-800/80 border border-slate-700/80 space-y-2.5\">\n          <div class=\"flex items-center justify-between\">\n            <span class=\"text-[10px] font-bold text-slate-400 uppercase tracking-wider\">Node Type</span>\n            <span class=\"px-2.5 py-0.5 rounded-full text-[11px] font-bold ${style.badge}\">\n              Gray Node \u2022 Unlinked Memory\n            </span>\n          </div>\n          <div class=\"p-2.5 rounded-xl bg-amber-950/30 border border-amber-800/40 text-amber-300 text-xs flex items-start gap-2\">\n            <i data-lucide=\"alert-circle\" class=\"w-4 h-4 text-amber-400 shrink-0 mt-0.5\"></i>\n            <div>\n              <div class=\"font-semibold text-[11px]\">Memory Not Included in Graph</div>\n              <div class=\"text-[10px] text-amber-400/80 mt-0.5\">This memory is stored in the database but not yet grounded to any Knowledge Graph entities or relations.</div>\n            </div>\n          </div>\n          <div class=\"pt-2 border-t border-slate-700/60 flex justify-between text-[11px] text-slate-300\">\n            <div>Category: <span class=\"text-white font-mono font-bold capitalize\">${escapeHtml(m.category || 'general')}</span></div>\n            <div>Author: <span class=\"text-emerald-400 font-mono font-bold\">${escapeHtml(m.agent_id || 'system')}</span></div>\n          </div>\n          <div class=\"flex justify-between text-[11px] text-slate-300\">\n            <div>Created: <span class=\"text-slate-400 font-mono\">${formatDate(m.created_at)}</span></div>\n            <div>Session: <span class=\"text-slate-400 font-mono truncate max-w-[120px]\">${escapeHtml(m.session_id || 'n/a')}</span></div>\n          </div>\n          ${m.tags && m.tags.length > 0 ? `\n            <div class=\"pt-2 border-t border-slate-700/60 flex flex-wrap gap-1\">\n              ${m.tags.map(t => `<span class=\"px-2 py-0.5 rounded-lg bg-white/5 text-slate-300 border border-white/10 font-mono text-[10px]\">#${escapeHtml(t)}</span>`).join('')}\n            </div>\n          ` : ''}\n        </div>\n\n        <!-- Full Memory Content -->\n        <div class=\"p-3.5 rounded-xl bg-white/5 border border-white/10 space-y-2 shadow-sm\">\n          <span class=\"text-[10px] font-bold text-slate-400 uppercase tracking-wider flex items-center justify-between\">\n            <span>Memory Content</span>\n            <span class=\"text-slate-500 font-mono text-[9px]\">${(m.content || '').length} chars</span>\n          </span>\n          <div class=\"prose-dark\">\n            ${renderMarkdown(m.content)}\n          </div>\n        </div>\n\n        ${m.metadata && Object.keys(m.metadata).length > 0 ? `\n          <div class=\"space-y-1\">\n            <span class=\"text-[11px] font-bold text-slate-400 uppercase tracking-wider\">Metadata</span>\n            <pre class=\"p-3 rounded-xl bg-black/40 border border-white/10 font-mono text-[11px] text-slate-300 overflow-x-auto\">${escapeHtml(JSON.stringify(m.metadata, null, 2))}</pre>\n          </div>\n        ` : ''}\n\n        <div class=\"p-3 rounded-xl bg-purple-950/20 border border-purple-500/20 text-purple-300 text-xs flex items-start gap-2\">\n          <i data-lucide=\"sparkles\" class=\"w-4 h-4 text-purple-400 shrink-0 mt-0.5\"></i>\n          <div>\n            <div class=\"font-semibold text-[11px]\">How to Ground into KG</div>\n            <div class=\"text-[10px] text-purple-300/80 mt-0.5\">Agents can ground this memory into entities by calling <code class=\"bg-black/30 px-1 py-0.5 rounded text-purple-200 font-mono\">link_entities</code> or passing <code class=\"bg-black/30 px-1 py-0.5 rounded text-purple-200 font-mono\">entities</code> & <code class=\"bg-black/30 px-1 py-0.5 rounded text-purple-200 font-mono\">relations</code> in <code class=\"bg-black/30 px-1 py-0.5 rounded text-purple-200 font-mono\">store_memory</code>.</div>\n          </div>\n        </div>\n      `;\n    }\n\n    function inspectRelation(edgeId) {\n      const rel = rawRelations.find(r => r.id === edgeId);\n      if (!rel) return;\n\n      const src = rawEntities.find(e => e.id === rel.src);\n      const dst = rawEntities.find(e => e.id === rel.dst);\n      const isSup = Boolean(rel.valid_to);\n      const evidenceMem = rawMemories.find(m => m.id === rel.memory_id);\n\n      const drawer = document.getElementById('inspectorDrawer');\n      const title = document.getElementById('inspectorTitle');\n      const content = document.getElementById('inspectorContent');\n\n      title.textContent = `Relation: ${rel.predicate}`;\n      drawer.classList.remove('translate-x-full');\n\n      content.innerHTML = `\n        <div class=\"p-3.5 rounded-2xl bg-white/5 border border-white/10 space-y-3\">\n          <div class=\"flex items-center justify-between\">\n            <span class=\"text-[10px] font-bold text-slate-400 uppercase tracking-wider\">Status</span>\n            ${isSup \n              ? '<span class=\"px-2 py-0.5 rounded-full text-[10px] bg-red-950 text-red-400 border border-red-800 font-semibold\">Superseded</span>'\n              : '<span class=\"px-2 py-0.5 rounded-full text-[10px] bg-emerald-950 text-emerald-400 border border-emerald-800 font-semibold\">Active</span>'\n            }\n          </div>\n\n          <div class=\"space-y-2 font-mono text-xs\">\n            <div class=\"flex items-center justify-between\">\n              <span class=\"text-slate-400\">Source:</span>\n              <button onclick=\"focusAndInspectNode('${rel.src}')\" class=\"text-emerald-400 hover:underline font-bold\">${escapeHtml(src ? src.name : rel.src)}</button>\n            </div>\n            <div class=\"flex items-center justify-between\">\n              <span class=\"text-slate-400\">Predicate:</span>\n              <span class=\"text-white font-bold bg-white/10 px-2 py-0.5 rounded\">${escapeHtml(rel.predicate)}</span>\n            </div>\n            <div class=\"flex items-center justify-between\">\n              <span class=\"text-slate-400\">Destination:</span>\n              <button onclick=\"focusAndInspectNode('${rel.dst}')\" class=\"text-sky-400 hover:underline font-bold\">${escapeHtml(dst ? dst.name : rel.dst)}</button>\n            </div>\n          </div>\n\n          <div class=\"pt-2 border-t border-white/10 text-[11px] text-slate-400 space-y-1\">\n            <div>Valid From: <span class=\"font-mono text-slate-200\">${formatDate(rel.valid_from)}</span></div>\n            ${rel.valid_to ? `<div>Valid To: <span class=\"font-mono text-red-300\">${formatDate(rel.valid_to)}</span></div>` : ''}\n          </div>\n        </div>\n\n        ${evidenceMem ? `\n          <div class=\"space-y-2\">\n            <span class=\"text-[11px] font-bold text-slate-400 uppercase tracking-wider\">Grounded Evidence Memory</span>\n            <div class=\"p-3.5 rounded-xl bg-purple-950/20 border border-purple-500/20 space-y-2.5\">\n              <div class=\"flex items-center justify-between\">\n                <span class=\"px-2 py-0.5 rounded-full text-[10px] bg-purple-950 text-purple-300 border border-purple-800 font-semibold uppercase tracking-wider\">${escapeHtml(evidenceMem.category)}</span>\n                <span class=\"text-[10px] text-slate-400 font-mono\">${formatDate(evidenceMem.created_at)}</span>\n              </div>\n              <div class=\"prose-dark\">\n                ${renderMarkdown(evidenceMem.content)}\n              </div>\n            </div>\n          </div>\n        ` : ''}\n      `;\n      lucide.createIcons();\n    }\n\n    function closeInspector() {\n      document.getElementById('inspectorDrawer').classList.add('translate-x-full');\n      selectedEntityId = null;\n    }\n\n    function focusAndInspectNode(nodeId) {\n      if (!network) return;\n      network.focus(nodeId, { scale: 1.2, animation: { duration: 500, easingFunction: 'easeInOutQuad' } });\n      inspectEntity(nodeId);\n    }\n\n    function isolateEntityNeighborhood(nodeId) {\n      focusCenterEntityId = nodeId;\n      focusHopDepth = 1;\n      renderGraph();\n      focusAndInspectNode(nodeId);\n    }\n\n    // --- SEARCH & AUTOCOMPLETE ---\n    function handleSearch(val) {\n      const q = val.trim().toLowerCase();\n      const dropdown = document.getElementById('searchDropdown');\n      const btnClear = document.getElementById('btnClearSearch');\n\n      if (!q) {\n        dropdown.classList.add('hidden');\n        btnClear.classList.add('hidden');\n        return;\n      }\n      btnClear.classList.remove('hidden');\n\n      const unlinkedEntities = getUnlinkedMemoryEntities();\n      const allSearchNodes = [...rawEntities, ...unlinkedEntities];\n\n      const matches = allSearchNodes.filter(e => {\n        if (e.name.toLowerCase().includes(q)) return true;\n        if (e.type && e.type.toLowerCase().includes(q)) return true;\n        if (e.aliases && e.aliases.some(a => a.toLowerCase().includes(q))) return true;\n        if (e.isMemoryNode && e.metadata?.full_content?.toLowerCase().includes(q)) return true;\n        return false;\n      }).slice(0, 10);\n\n      if (matches.length === 0) {\n        dropdown.innerHTML = '<div class=\"px-3 py-2 text-slate-500 text-xs italic\">No matching entities found</div>';\n        dropdown.classList.remove('hidden');\n        return;\n      }\n\n      dropdown.innerHTML = matches.map(e => {\n        const style = getTypeStyle(e.type);\n        return `\n          <button onclick=\"selectSearchResult('${e.id}')\" class=\"w-full px-3 py-2 text-left hover:bg-white/10 flex items-center justify-between border-b border-white/5 last:border-0 transition\">\n            <div class=\"overflow-hidden\">\n              <div class=\"text-white font-bold text-xs truncate\">${escapeHtml(e.name)}</div>\n              ${e.aliases && e.aliases.length > 0 ? `<div class=\"text-[10px] text-slate-400 truncate\">aka: ${escapeHtml(e.aliases.join(', '))}</div>` : ''}\n            </div>\n            <span class=\"text-[10px] font-bold px-2 py-0.5 rounded-full ${style.badge}\">${escapeHtml(e.type)}</span>\n          </button>\n        `;\n      }).join('');\n\n      dropdown.classList.remove('hidden');\n    }\n\n    function selectSearchResult(entityId) {\n      document.getElementById('searchDropdown').classList.add('hidden');\n      focusAndInspectNode(entityId);\n    }\n\n    function clearSearch() {\n      document.getElementById('searchInput').value = '';\n      document.getElementById('searchDropdown').classList.add('hidden');\n      document.getElementById('btnClearSearch').classList.add('hidden');\n    }\n\n    // --- TOOLBAR CONTROLS ---\n    function fitGraph() {\n      if (network) network.fit({ animation: { duration: 600, easingFunction: 'easeInOutQuad' } });\n    }\n\n    function togglePhysics() {\n      isPhysicsActive = !isPhysicsActive;\n      network.setOptions({ physics: { enabled: isPhysicsActive } });\n      const btn = document.getElementById('btnPhysicsToggle');\n      if (isPhysicsActive) {\n        btn.classList.add('text-emerald-400');\n        btn.classList.remove('text-slate-400');\n      } else {\n        btn.classList.remove('text-emerald-400');\n        btn.classList.add('text-slate-400');\n      }\n    }\n\n    function toggleLayoutMode() {\n      isHierarchical = !isHierarchical;\n      if (isHierarchical) {\n        network.setOptions({\n          layout: {\n            hierarchical: {\n              enabled: true,\n              direction: 'LR',\n              sortMethod: 'directed',\n              levelSeparation: 160,\n              nodeSpacing: 110\n            }\n          }\n        });\n      } else {\n        network.setOptions({\n          layout: { hierarchical: { enabled: false } },\n          physics: { enabled: isPhysicsActive }\n        });\n      }\n      fitGraph();\n    }\n\n    function exportPNG() {\n      if (!network) return;\n      const canvas = document.querySelector('#graphContainer canvas');\n      if (!canvas) return;\n      const dataURL = canvas.toDataURL('image/png');\n      const a = document.createElement('a');\n      a.href = dataURL;\n      a.download = `raymond-knowledge-graph-${Date.now()}.png`;\n      a.click();\n    }\n\n    // --- SUPABASE DATA SYNC ---\n    async function fetchFromSupabase(url, key) {\n      updateStatusBadge('connecting', 'Connecting...');\n      \n      const cleanUrl = url.replace(/\\/+$/, '');\n      const headers = {\n        'apikey': key,\n        'Authorization': `Bearer ${key}`,\n        'Content-Type': 'application/json'\n      };\n\n      try {\n        const [entRes, relRes, memRes, memEntRes] = await Promise.all([\n          fetch(`${cleanUrl}/rest/v1/entities?select=*&order=created_at.desc&limit=500`, { headers }),\n          fetch(`${cleanUrl}/rest/v1/relations?select=*&order=created_at.desc&limit=1000`, { headers }),\n          fetch(`${cleanUrl}/rest/v1/memories?select=id,agent_id,session_id,category,content,tags,created_at,metadata&order=created_at.desc&limit=300`, { headers }),\n          fetch(`${cleanUrl}/rest/v1/memory_entities?select=memory_id,entity_id`, { headers }),\n        ]);\n\n        if (!entRes.ok) throw new Error(`Entities query failed: ${entRes.statusText}`);\n        if (!relRes.ok) throw new Error(`Relations query failed: ${relRes.statusText}`);\n\n        rawEntities = await entRes.json();\n        rawRelations = await relRes.json();\n        rawMemories = memRes.ok ? await memRes.json() : [];\n        rawMemoryEntities = memEntRes.ok ? await memEntRes.json() : [];\n\n        localStorage.setItem('raymond_supabase_url', cleanUrl);\n        localStorage.setItem('raymond_supabase_key', key);\n\n        updateStatusBadge('connected', 'Live Supabase');\n        closeSettingsModal();\n        renderGraph();\n        setTimeout(fitGraph, 300);\n      } catch (err) {\n        console.error(\"Supabase fetch error:\", err);\n        updateStatusBadge('error', 'Sync Failed');\n        throw err;\n      }\n    }\n\n    function loadDemoDataset() {\n      rawEntities = JSON.parse(JSON.stringify(DEMO_DATASET.entities));\n      rawRelations = JSON.parse(JSON.stringify(DEMO_DATASET.relations));\n      rawMemories = JSON.parse(JSON.stringify(DEMO_DATASET.memories));\n      rawMemoryEntities = JSON.parse(JSON.stringify(DEMO_DATASET.memory_entities));\n\n      updateStatusBadge('demo', 'Demo Dataset');\n      closeSettingsModal();\n      renderGraph();\n      setTimeout(fitGraph, 200);\n    }\n\n    async function refreshData() {\n      try {\n        const proxyRes = await fetch('/api/graph?refresh=true');\n        if (proxyRes.ok) {\n          const graphJson = await proxyRes.json();\n          if (graphJson && graphJson.entities) {\n            applyGraphJson(graphJson, 'Live Edge Proxy');\n            return;\n          }\n        }\n      } catch (_) {}\n\n      const url = document.getElementById('cfgSupabaseUrl').value.trim();\n      const key = document.getElementById('cfgSupabaseKey').value.trim();\n      if (url && key) {\n        try {\n          await fetchFromSupabase(url, key);\n        } catch (e) {\n          alert(\"Failed to refresh from Supabase: \" + e.message);\n        }\n      } else {\n        openSettingsModal();\n      }\n    }\n\n    function updateStatusBadge(state, text) {\n      const indicator = document.getElementById('statusIndicator');\n      const textElem = document.getElementById('statusText');\n      textElem.textContent = text;\n\n      indicator.className = 'w-2 h-2 rounded-full';\n      if (state === 'connected') {\n        indicator.classList.add('bg-emerald-400');\n      } else if (state === 'connecting') {\n        indicator.classList.add('bg-amber-400', 'animate-pulse');\n      } else if (state === 'demo') {\n        indicator.classList.add('bg-sky-400');\n      } else if (state === 'disconnected') {\n        indicator.classList.add('bg-slate-500');\n      } else {\n        indicator.classList.add('bg-red-400');\n      }\n    }\n\n    // --- MODAL CONTROLS ---\n    function openSettingsModal() {\n      document.getElementById('settingsModal').classList.remove('hidden');\n      lucide.createIcons();\n    }\n\n    function closeSettingsModal() {\n      document.getElementById('settingsModal').classList.add('hidden');\n    }\n\n    async function saveAndConnectSupabase() {\n      const url = document.getElementById('cfgSupabaseUrl').value.trim();\n      const key = document.getElementById('cfgSupabaseKey').value.trim();\n      const alertBox = document.getElementById('modalStatusAlert');\n\n      if (!url || !key) {\n        alertBox.className = 'p-3 rounded-lg border text-xs bg-red-950/60 text-red-300 border-red-800';\n        alertBox.textContent = 'Please enter both Supabase URL and API Key.';\n        alertBox.classList.remove('hidden');\n        return;\n      }\n\n      alertBox.className = 'p-3 rounded-lg border text-xs bg-amber-950/60 text-amber-300 border-amber-800';\n      alertBox.textContent = 'Connecting to Supabase...';\n      alertBox.classList.remove('hidden');\n\n      try {\n        await fetchFromSupabase(url, key);\n        alertBox.classList.add('hidden');\n      } catch (err) {\n        alertBox.className = 'p-3 rounded-lg border text-xs bg-red-950/60 text-red-300 border-red-800';\n        alertBox.textContent = `Connection error: ${err.message}`;\n        alertBox.classList.remove('hidden');\n      }\n    }\n\n    // --- UTILITIES ---\n    let isDrawerExpanded = false;\n    function toggleDrawerWidth() {\n      const drawer = document.getElementById('inspectorDrawer');\n      const icon = document.getElementById('iconDrawerWidth');\n      isDrawerExpanded = !isDrawerExpanded;\n      if (isDrawerExpanded) {\n        drawer.classList.remove('w-96');\n        drawer.classList.add('w-full', 'md:w-[620px]');\n        icon.setAttribute('data-lucide', 'minimize-2');\n      } else {\n        drawer.classList.remove('w-full', 'md:w-[620px]');\n        drawer.classList.add('w-96');\n        icon.setAttribute('data-lucide', 'maximize-2');\n      }\n      lucide.createIcons();\n    }\n\n    function renderMarkdown(md) {\n      if (!md) return '';\n      if (typeof marked !== 'undefined') {\n        try {\n          return marked.parse(String(md));\n        } catch (e) {\n          console.warn(\"Markdown parse error:\", e);\n        }\n      }\n      return escapeHtml(md).replace(/\\n/g, '<br>');\n    }\n\n    function escapeHtml(str) {\n      if (!str) return '';\n      return String(str)\n        .replace(/&/g, '&amp;')\n        .replace(/</g, '&lt;')\n        .replace(/>/g, '&gt;')\n        .replace(/\"/g, '&quot;')\n        .replace(/'/g, '&#039;');\n    }\n\n    function formatDate(ts) {\n      if (!ts) return '';\n      try {\n        const d = new Date(ts);\n        return d.toLocaleDateString() + ' ' + d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });\n      } catch (_) {\n        return String(ts);\n      }\n    }\n  </script>\n</body>\n</html>";

export function getViewerHtml(defaultUrl: string = "", defaultKey: string = ""): string {
  if (defaultUrl || defaultKey) {
    const injection = `<script>window.__DEFAULT_SUPABASE_URL__ = ${JSON.stringify(defaultUrl)}; window.__DEFAULT_SUPABASE_KEY__ = ${JSON.stringify(defaultKey)};</script>`;
    return rawHtml.replace("<head>", `<head>
  ${injection}`);
  }
  return rawHtml;
}
